import json
from pathlib import Path
b=Path(__file__).parent
payload={k:json.loads((b/(v+'.json')).read_text()) for k,v in [('summary','summary'),('findings','findings'),('coverage','coverage'),('headwords','headword_coverage')]}
replacement=json.loads((b/'sentence_replacement.json').read_text()) if (b/'sentence_replacement.json').exists() else None
payload['applied']={'LANG-006':'Replaced with ohmaen I Ya. — I love you. '+replacement.get('translation_note','')+' The earlier missing-my flag is superseded by this approved contextual explanation. The simpler replacement remains in use.'} if replacement else {}
if (b/'applied_results.json').exists():
 payload['applied'].update(json.loads((b/'applied_results.json').read_text())['outcomes'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Celan · Example sentence audit</title><style>
body{font:16px/1.55 system-ui;background:#f5f7fa;color:#213346;margin:0}main{max-width:1100px;margin:auto;padding:30px 20px}h1{font-size:34px}h2{font-size:23px}article,.intro{background:white;border:1px solid #d8e1e9;border-radius:12px;padding:22px;margin:20px 0}p{max-width:950px}.muted{color:#596b7c}.tag{font-size:14px;color:#17578c}input,textarea,select,button{font:inherit;border:1px solid #b9c6d3;border-radius:6px;padding:9px}button{cursor:pointer;background:#eaf2fc}button:disabled{opacity:.45;cursor:default}textarea{box-sizing:border-box;width:100%;min-height:85px}label{display:block;margin:12px 0 5px}nav,.filters{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.filters input{flex:1;min-width:220px}.example{border-left:3px solid #9ab6d0;padding:5px 16px;margin:15px 0}.example p{margin:5px 0}summary{cursor:pointer;font-weight:600}table{border-collapse:collapse;width:100%;margin:15px 0}td,th{border-bottom:1px solid #dce4ec;text-align:left;padding:10px;vertical-align:top}a{color:#185c93}.scroll{overflow:auto}#notice{color:#355c45}pre{white-space:pre-wrap}small{display:block}.count{font-weight:600}
</style><main><h1>Example sentence audit</h1><p class="muted">Celan Dictionary · September 23, 2026</p><section class="intro"><h2 id="stats"></h2><p><strong>Your 13 exported approvals are applied locally. The earlier LANG-006 clarification is preserved. Other findings remain for review.</strong> This review separates meaning questions, misplaced examples, teaching material, duplicates, and app presentation problems. An issue can affect several entries, and one sentence can have several flags.</p><p id="scope"></p><details><summary>What “audited” means here</summary><p id="limits"></p><p>Every source record and every app-selected inline example is listed below. Structural checks cover the whole inventory. Meaning checks are targeted against the current dictionary; unflagged sentences are not automatically certified correct. Earlier approvals are preserved in the evidence, and this report does not silently reverse them.</p></details><p>You can approve, reject, modify, or defer each finding. The proposal and individual sentence fields are editable. Export your decisions when ready; saved browser notes do not update the app.</p><nav><button id="export">Export decisions</button><button id="import">Import decisions</button><input id="file" type="file" accept="application/json" hidden></nav><p id="notice" role="status"></p></section><h2>Findings</h2><div class="filters"><input id="search" type="search" aria-label="Search findings" placeholder="Word, sentence, example ID, or issue…"><select id="category" aria-label="Finding category"><option>All categories</option></select><select id="status" aria-label="Review status"><option>All decisions</option><option>Not reviewed</option><option>Approve proposal</option><option>Approve with edits</option><option>Keep current</option><option>Needs discussion</option></select></div><p id="found" class="count" role="status"></p><div id="findings"></div><nav><button id="prev">Previous findings</button><span id="page"></span><button id="next">Next findings</button></nav><p><a href="draft_batch_1.md">Review the first draft batch for missing examples</a></p><h2>Original audit sentence records</h2><p>This includes source records that do not appear in the first five examples for any entry. “No flag” means no issue identified by these checks.</p><input id="coverageSearch" type="search" aria-label="Search all sentence records" placeholder="Search the complete inventory"><p id="coverageCount"></p><div class="scroll"><table><thead><tr><th>Record</th><th>Celan / English</th><th>Visible under</th><th>Flags</th></tr></thead><tbody id="coverage"></tbody></table></div><nav><button id="covPrev">Previous records</button><span id="covPage"></span><button id="covNext">Next records</button></nav><details><summary>Headword coverage: all 1,496 entries</summary><div class="scroll"><table><thead><tr><th>Entry</th><th>Available examples</th><th>Shown</th></tr></thead><tbody id="headwords"></tbody></table></div></details></main><script>
const data=PAYLOAD;const key='celan-example-audit-v1';const revision=data.summary.capturedAt;let decisions={},page=0,covPage=0;const size=15,covSize=40;try{decisions=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const options=['Not reviewed','Approve proposal','Approve with edits','Keep current','Needs discussion'];
function save(){try{localStorage.setItem(key,JSON.stringify(decisions));$('#notice').textContent='Saved in this browser. Export decisions to send them for implementation.'}catch{$('#notice').textContent='Browser storage unavailable. Export before closing.'}}
function matching(){const q=$('#search').value.toLowerCase(),cat=$('#category').value,status=$('#status').value;return data.findings.filter(f=>(!q||JSON.stringify(f).toLowerCase().includes(q))&&(cat==='All categories'||f.category===cat)&&(status==='All decisions'||(decisions[f.id]?.decision||'Not reviewed')===status))}
function render(){const found=matching();page=Math.min(page,Math.max(0,Math.ceil(found.length/size)-1));$('#found').textContent=`${found.length} findings match · ${data.summary.flagged_sentence_records} distinct sentence records flagged overall`;
$('#findings').innerHTML=found.slice(page*size,(page+1)*size).map(f=>{const d=decisions[f.id]||{};return `<article id="${esc(f.id)}"><span class="tag">${esc(f.id)} · ${esc(f.category)} · ${esc(f.confidence)}</span><h2>${esc(f.title)}</h2>${data.applied[f.id] ? `<p><strong>Applied:</strong> ${esc(data.applied[f.id])}</p>` : ''}<p><strong>Why flagged:</strong> ${esc(f.why)}</p>${f.records.map((r,i)=>{const edit=d.edits?.[r.id]||{};return `<div class="example"><strong>${esc(r.id)}</strong><p>${esc(r.celan)}</p><p>“${esc(r.english)}”</p><small>${esc(r.type)} · Currently visible under: ${esc(r.displayed_under.join(', ')||'No entry’s first five examples')}</small><details><summary>Evidence and proposed sentence edit</summary><p>${esc(r.previous_approval ? 'Recorded review status: '+r.previous_approval : 'No source review status')} ${esc(r.notes)}</p><label>Proposed Celan (blank means no replacement supplied)<textarea data-id="${esc(f.id)}" data-record="${esc(r.id)}" data-field="celan">${esc(edit.celan ?? (i===0?f.suggested_celan:''))}</textarea></label><label>Proposed English<textarea data-id="${esc(f.id)}" data-record="${esc(r.id)}" data-field="english">${esc(edit.english ?? (i===0?f.suggested_english:''))}</textarea></label></details></div>`}).join('')}${f.headwords.length?`<details><summary>Affected entries (${f.headwords.length})</summary><p>${f.headwords.map(esc).join(', ')}</p></details>`:''}<label>Proposed action<textarea data-id="${esc(f.id)}" data-field="proposal">${esc(d.proposal??f.proposal)}</textarea></label><label>Decision<select data-id="${esc(f.id)}" data-field="decision">${options.map(v=>`<option ${v===(d.decision||'Not reviewed')?'selected':''}>${v}</option>`).join('')}</select></label><label>Your notes<textarea data-id="${esc(f.id)}" data-field="notes">${esc(d.notes||'')}</textarea></label></article>`}).join('');$('#page').textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(found.length/size))}`;$('#prev').disabled=page===0;$('#next').disabled=(page+1)*size>=found.length;}
function renderCoverage(){const q=$('#coverageSearch').value.toLowerCase();const found=data.coverage.filter(r=>JSON.stringify(r).toLowerCase().includes(q));covPage=Math.min(covPage,Math.max(0,Math.ceil(found.length/covSize)-1));$('#coverageCount').textContent=`${found.length} records match`;$('#coverage').innerHTML=found.slice(covPage*covSize,(covPage+1)*covSize).map(r=>`<tr><td>${esc(r.id)}<small>${esc(r.type)}</small></td><td>${esc(r.celan)}<br>“${esc(r.english)}”</td><td>${r.placements.filter(p=>p.visible).map(p=>`<a href="../../dictionary/index.html#word=${encodeURIComponent(p.headword_id)}">${esc(p.headword)}</a>`).join(', ')||'Not in a first-five list'}</td><td>${r.flags.map(f=>`<button class="jump" data-flag="${esc(f)}">${esc(f)}</button>`).join(' ')||'No flag'}</td></tr>`).join('');$('#covPage').textContent=`Page ${covPage+1} of ${Math.max(1,Math.ceil(found.length/covSize))}`;$('#covPrev').disabled=covPage===0;$('#covNext').disabled=(covPage+1)*covSize>=found.length;}
$('#stats').textContent=`${data.summary.source_records.toLocaleString()} source records · ${data.summary.headwords.toLocaleString()} headwords · ${data.summary.flags} findings`;$('#scope').textContent=data.summary.scope;$('#limits').textContent=data.summary.limits;
$('#category').innerHTML+=[...new Set(data.findings.map(f=>f.category))].map(c=>`<option>${esc(c)}</option>`).join('');$('#headwords').innerHTML=data.headwords.map(g=>`<tr><td><a href="../../dictionary/index.html#word=${encodeURIComponent(g.id)}">${esc(g.term)}</a></td><td>${g.available}</td><td>${g.visible}</td></tr>`).join('');
$('#findings').addEventListener('input',e=>{const {id,field,record}=e.target.dataset;if(!id||!field)return;const d=decisions[id]||={};if(record){d.edits||={};(d.edits[record]||={})[field]=e.target.value}else d[field]=e.target.value;save()});
for(const id of ['#search','#category','#status'])$(id).addEventListener('input',()=>{page=0;render()});$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};$('#coverageSearch').addEventListener('input',()=>{covPage=0;renderCoverage()});$('#covPrev').onclick=()=>{covPage--;renderCoverage()};$('#covNext').onclick=()=>{covPage++;renderCoverage()};$('#coverage').addEventListener('click',e=>{const f=e.target.dataset.flag;if(!f)return;$('#search').value=f;$('#category').value='All categories';$('#status').value='All decisions';page=0;render();$('#findings').scrollIntoView({behavior:'smooth'})});
function exportData(){return {audit:'example-sentences-v1',revision,decisions:Object.fromEntries(data.findings.map(f=>{const d=decisions[f.id]||{};return [f.id,{decision:d.decision||'Not reviewed',proposal:d.proposal??f.proposal,notes:d.notes||'',edits:Object.fromEntries(f.records.map((r,i)=>[r.id,{celan:d.edits?.[r.id]?.celan??(i===0?f.suggested_celan:''),english:d.edits?.[r.id]?.english??(i===0?f.suggested_english:'')}]))}]}))}}
$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(exportData(),null,2)],{type:'application/json'}));a.download='celan-example-sentence-decisions.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const p=JSON.parse(await e.target.files[0].text());if(p.audit!=='example-sentences-v1'||p.revision!==revision||!p.decisions)throw Error('File does not match this audit revision');for(const f of data.findings){const d=p.decisions[f.id];if(!d||typeof d!=='object')continue;const clean={decision:options.includes(d.decision)?d.decision:'Not reviewed',proposal:typeof d.proposal==='string'?d.proposal:f.proposal,notes:typeof d.notes==='string'?d.notes:'',edits:{}};for(const r of f.records){const v=d.edits?.[r.id];if(v&&typeof v==='object')clean.edits[r.id]={celan:typeof v.celan==='string'?v.celan:'',english:typeof v.english==='string'?v.english:''}}decisions[f.id]=clean}save();render()}catch(err){$('#notice').textContent='Import failed: '+err.message}};render();renderCoverage();
</script></html>'''
(b/'review.html').write_text(page.replace('PAYLOAD',json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')))
md=['# Dictionary example sentence audit','',json.dumps(payload['summary'],indent=2),'']
for f in payload['findings']:
 md += ['## '+f['id']+' — '+f['title'],'',f['confidence']+' · '+f['category'],'',f['why'],'','Proposed action: '+f['proposal'],'']
 for r in f['records']:md+=['- '+r['id']+': '+r['celan']+' — '+r['english']]
 if f['headwords']:md+=['','Affected entries: '+', '.join(f['headwords'])]
 md+=['']
(b/'review.md').write_text('\n'.join(md))
